def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MIN_SUPPLY = 15
    MAX_SUPPLY = 25

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opps = []
    prev_bids = []
    moderate_bids = []
    dangerous_bids = []
    eric_like_bid = None

    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opps.append((oid, opp))
            prev = opp.get('previous_trace', {}) or {}
            bid = prev.get('bid')
            if bid is not None:
                prev_bids.append(float(bid))
                if bid <= 150:
                    moderate_bids.append(float(bid))
                if bid >= 80:
                    dangerous_bids.append(float(bid))
                if opp.get('daily_salary') == 70 and opp.get('water_requirement') == 13:
                    if eric_like_bid is None or float(bid) < eric_like_bid:
                        eric_like_bid = float(bid)

    if not alive_opps:
        return float(min(budget, 18.0))

    slots = max(1, int(supply // WATER_REQ))
    alive_count = len(alive_opps) + 1
    scarcity = alive_count > slots
    very_tight = slots <= 1

    if eric_like_bid is None:
        if moderate_bids:
            eric_like_bid = max(moderate_bids)
        elif prev_bids:
            eric_like_bid = min(max(prev_bids), 90.0)
        else:
            eric_like_bid = 45.0

    base = 24.0
    if scarcity:
        base = 48.0
    if very_tight:
        base = 58.0

    target = max(base, eric_like_bid + 2.5)

    if dangerous_bids and hp > 3 and no_water_days == 0:
        target = min(target, 52.0)

    if hp <= 2 or no_water_days >= 2:
        target = max(target, eric_like_bid + 8.0, 72.0)
    elif hp <= 4 or no_water_days >= 1:
        target = max(target, eric_like_bid + 5.0, 60.0)

    if day >= 8:
        target += 6.0
    if day >= 9 and (hp <= 4 or scarcity):
        target += 8.0

    reserve = 0.0
    if hp > 4 and no_water_days == 0:
        reserve = DAILY_SALARY * 1.2
    elif hp > 2:
        reserve = DAILY_SALARY * 0.6

    max_affordable = max(0.0, budget - reserve)
    if hp <= 2 or no_water_days >= 2:
        max_affordable = budget

    bid = min(target, max_affordable if max_affordable > 0 else budget)

    if not scarcity and hp > 4 and no_water_days == 0:
        bid = min(bid, 36.0)

    if bid < 0:
        bid = 0.0
    if budget < 12 and (hp <= 2 or no_water_days >= 2):
        bid = budget

    return float(min(budget, max(0.0, bid)))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']

    # If we're already in danger, prioritize survival.
    if my_status['hp'] <= 2:
        return min(my_status['budget'], DAILY_SALARY * 0.95)

    alive_opponents = []
    for opp in opponents_status.values():
        if opp.get('alive', False) and opp.get('budget', 0) > 0:
            alive_opponents.append(opp)

    # Default safe bid baseline: enough to be competitive without wasting budget.
    # Scale with supply: higher supply -> lower urgency.
    supply_norm = (supply - MIN_SUPPLY) / (MAX_SUPPLY - MIN_SUPPLY) if (MAX_SUPPLY - MIN_SUPPLY) != 0 else 0.5
    supply_norm = max(0.0, min(1.0, float(supply_norm)))

    base = DAILY_SALARY * (0.62 - 0.25 * supply_norm)  # 0.62 at low supply, 0.37 at high supply

    # React to yesterday's bids: Cindy likely exhausted, Eric low, Alex moderate.
    prev_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev['bid']))
            except Exception:
                pass

    if prev_bids:
        highest_prev_bid = max(prev_bids)
        # If someone previously bid extremely high, they likely ran out of budget.
        # We can shade downward.
        if highest_prev_bid >= DAILY_SALARY * 5.0:
            base *= 0.78
        # If there was moderate competition, bid enough to secure water.
        elif highest_prev_bid >= DAILY_SALARY * 0.85:
            base *= 0.95
        else:
            base *= 1.05

    # If our no-water days are high, increase urgency.
    no_water_days = my_status.get('no_water_days', 0)
    if no_water_days >= 2:
        base *= 1.15
    if no_water_days >= 4:
        base *= 1.35

    # Cap to avoid suicidal spending; also ensure we don't bid more than budget.
    # Target is often around 0.5-0.9 of daily salary depending on pressure.
    bid = min(my_status['budget'], max(1.0, base))

    # Small final adjustment: if supply is very low, be more aggressive.
    if supply <= MIN_SUPPLY + 1.0:
        bid = min(my_status['budget'], bid * 1.12)

    return float(bid)

